import json
from pathlib import Path

ROOT = Path(__file__).parent
groups = []
screens = []

def group(key, title, description):
    groups.append(dict(key=key,title=title,description=description))

def s(key,title,subtitle='',blocks=None,actions=None,back=None,tab=None,note='',states=None):
    screens.append(dict(key=key,group=groups[-1]['key'],title=title,subtitle=subtitle,blocks=blocks or [],actions=actions or [],back=back,tab=tab,note=note,states=states or []))

def a(label,to,style='primary'): return dict(label=label,to=to,style=style)
def b(kind,title='',body='',to=None,**kw): return dict(kind=kind,title=title,body=body,to=to,**kw)
def field(label,value,hint=''): return b('field',label,value,hint=hint)
def row(label,body,to,icon='leaf'): return b('row',label,body,to,icon=icon)
def card(title,body,to=None,icon='leaf'): return b('card',title,body,to,icon=icon)
def photo(asset='monstera',height=150): return b('photo',asset,height=height)
def msg(title,body,icon='check'): return b('notice',title,body,icon=icon)
def choices(items): return b('choices',items=items)

