inventory = dict(product='PlantMe 2.0',version='2026-10-07',viewport=dict(width=375,height=667),groups=groups,screens=screens)
keys={x['key'] for x in screens}
missing=[]
for x in screens:
    targets=[z['to'] for z in x['actions']+x['states']]+[z.get('to') for z in x['blocks']]+[x['back']]
    for target in filter(None,targets):
        if target not in keys: missing.append((x['key'],target))
assert not missing, missing
assert len(keys)==len(screens)
(ROOT/'inventory.json').write_text(json.dumps(inventory,ensure_ascii=False,indent=2))
print(json.dumps(dict(screens=len(screens),groups=len(groups),missingRoutes=missing),ensure_ascii=False))
